// PR: "extract reusable hooks"

// hook 1 — used only by ProfilePage, just wraps one useState
+function useName() {
+  const [name, setName] = useState("");
+  return { name, setName };
+}

// hook 2 — used by ProfilePage and SearchBar (real duplication)
+function useUser(id: string) {
+  const [user, setUser] = useState<User | null>(null);
+  const [loading, setLoading] = useState(true);
+  useEffect(() => {
+    setLoading(true);
+    fetchUser(id).then((u) => {
+      setUser(u);
+      setLoading(false);
+    });
+  }, [id]);
+  return { user, loading };
+}
